"""Build the static GitHub Pages website from a small shared template."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
SITE=ROOT/'site'
REPO='https://github.com/brandenskaggs-rgb/signalpier'
LOGO='<svg viewBox="0 0 36 36" fill="none" aria-hidden="true"><path d="M5 29V17M13 29V8M21 29V3M29 29V12" stroke="currentColor" stroke-width="4"/><path d="M3 33h30" stroke="currentColor" stroke-width="2"/></svg>'
def page(name,title,body,description):
    nav=''.join(f'<a href="{href}"'+(' class="current"' if href==name else '')+f'>{label}</a>' for href,label in [('index.html','Overview'),('downloads.html','Downloads'),('guide.html','Get started'),('roadmap.html','Project')])
    text=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{description}"><meta name="theme-color" content="#2249d8"><title>{title} · SignalPier</title><link rel="icon" href="icon.svg" type="image/svg+xml"><link rel="stylesheet" href="site.css"><script src="site.js" defer></script></head><body><div class="wrap"><header class="nav"><a class="logo" href="index.html">{LOGO}SignalPier</a><nav class="links" aria-label="Main navigation">{nav}<a class="nav-cta" href="{REPO}">GitHub ↗</a></nav></header><main>{body}</main><footer class="footer"><a class="logo" href="index.html">{LOGO}SignalPier</a><span>Open source. Built for the curious operator.</span><div><a href="{REPO}/blob/main/LICENSE">MIT license</a><a href="{REPO}/issues">Report an issue</a><a href="guide.html#validation">Validation status</a></div></footer></div></body></html>'''
    (SITE/name).write_text(text,encoding='utf-8')

page('index.html','Your radio. A bigger horizon.',f'''
<section class="hero"><div><p class="eyebrow">OPEN-SOURCE RADIO WORKBENCH / PI 3 FIRST</p><h1>Your radio.<br>A bigger<br><em>horizon.</em></h1><p class="lede">Turn a Raspberry Pi into your radio desk. Explore the spectrum, decode supported sensor signals, and keep the world in view—all from your computer's browser.</p><div class="actions"><a class="button primary" href="https://github.com/brandenskaggs-rgb/signalpier/releases/download/v0.1.0-alpha.1/signalpier_0.1.0-alpha.1_arm64.deb">Download for Raspberry Pi 3 <span>↓</span></a><a class="button" href="guide.html">See how it works <span>↗</span></a></div><p class="hero-note"><i class="dot"></i> ARM64 · 64-bit Raspberry Pi OS · v0.1 alpha</p></div><div class="radio"><div class="radio-top"><span>SIGNALPIER / SPECTRUM</span><span>ILLUSTRATIVE PREVIEW</span></div><div class="frequency" id="frequency">433.920 <small>MHz</small></div><canvas id="hero-scope" width="520" height="280" aria-label="Illustrative radio spectrum and waterfall; not live reception"></canvas><div class="radio-scale"><span>LOWER FREQUENCY</span><span>RECEIVE POWER</span><span>HIGHER FREQUENCY</span></div><div class="band-controls" aria-label="Preview frequency"><button data-band="145.500">VHF</button><button class="selected" data-band="433.920">UHF</button><button data-band="915.000">915 MHz</button></div></div></section>
<div class="strip"><div>PI 3 B / B+<span>Primary hardware target</span></div><div>SMALL APP INSTALL<span>For your existing 64-bit Pi OS</span></div><div>ONE RECEIVER JOB<span>Bounded captures and memory</span></div><div>YOUR BROWSER<span>No dedicated Pi screen needed</span></div></div>
<section class="section"><div class="section-head"><div><p class="eyebrow">ONE STATION. SEVERAL WAYS TO EXPLORE.</p><h2>From the band<br>to the bigger picture.</h2></div><p>A focused toolkit for the things you actually want to do at your station. Every mode tells you where its data comes from.</p></div><div class="features"><article class="feature"><span class="icon">⌁</span><h3>See the spectrum</h3><p>Sweep a frequency range, inspect the waterfall, find signal candidates, and export a capture. RTL-SDR tools do the receiving.</p><span class="label">RTL_POWER · RECEIVE ONLY</span></article><article class="feature"><span class="icon">{{ }}</span><h3>Read the packets</h3><p>Inspect supported sensor protocols with rtl_433. See decoded fields from compatible weather stations and other devices.</p><span class="label">RTL_433 · SUPPORTED PROTOCOLS</span></article><article class="feature"><span class="icon">◷</span><h3>Keep the station clock</h3><p>UTC, local time, a world day/night map, Maidenhead locators, solar times, and DX bearings. Fetch timestamped NOAA readings when online.</p><span class="label">OFFLINE CLOCK · OPTIONAL NOAA</span></article></div></section>
<section class="section architecture"><div class="copy"><p class="eyebrow">SMALL BOARD. SENSIBLE WORKLOAD.</p><h2>Let the Pi receive.<br>Let your screen shine.</h2><p>The Pi 3 has 1 GB of RAM. SignalPier uses a small Python server and native receiver tools, while your laptop or phone draws the maps and charts.</p><p>No desktop environment, containers, or Node.js are required on the Pi. Captures are limited, plotted data is capped, and the receiver handles one job at a time.</p><a class="button" href="guide.html#receiver">Check the hardware →</a></div><div class="wiring"><div class="wire-box"><strong>ANTENNA + USB SDR</strong>Your compatible receiver</div><div class="wire-label">↓ USB · RADIO SAMPLES</div><div class="wire-box"><strong>RASPBERRY PI 3</strong>SignalPier + native decoder tools</div><div class="wire-label">↓ SSH TUNNEL · LOCAL NETWORK</div><div class="wire-ends"><div class="wire-box"><strong>YOUR COMPUTER</strong>Browser dashboard</div><div class="wire-box"><strong>YOUR WORK</strong>Capture exports</div></div></div></section>
<section class="section"><div class="section-head"><div><p class="eyebrow">EXPLORE WITHOUT A RECEIVER</p><h2>A useful place to begin.</h2></div><p>Demo captures are explicitly labeled synthetic. The encryption lab uses real browser cryptography but does not transmit over radio.</p></div><div class="features"><article class="feature"><h3>Try a demo capture</h3><p>Learn the controls and inspect sample data before plugging in an SDR. Hardware mode never substitutes demo signals.</p></article><article class="feature"><h3>Experiment with encryption</h3><p>Generate a key, encrypt your own text with AES-256-GCM, and verify the message. Keys stay in the browser session.</p></article><article class="feature"><h3>Build the next feature</h3><p>Readable Python and JavaScript, an MIT-licensed application, test coverage, and documented app packaging.</p><a class="button" href="{REPO}">Explore the source ↗</a></article></div></section>
<aside class="release-banner"><div><h3>Early software. Clear expectations.</h3><p>The app is packaged for Pi 3. ARM64 software checks and physical receiver validation are reported separately.</p></div><a class="button light" href="guide.html#validation">Read the test status →</a></aside>
''','SignalPier is an open-source radio workbench for Raspberry Pi 3: spectrum sweeps, sensor decoding, a station clock and a local encryption lab.')

page('downloads.html','Download the app',f'''
<section class="page-title"><p class="eyebrow">SIGNALPIER / RASPBERRY PI APP</p><h1>Download. Install.<br>Explore.</h1><p>Your Pi already has an operating system. Add SignalPier to it, then open your radio dashboard in the browser.</p></section>
<article class="download-card featured single-download"><p class="eyebrow">RASPBERRY PI 3 B / B+ · 64-BIT PI OS</p><h2>SignalPier</h2><p>Spectrum scans, supported sensor decoding, a station clock, and a local encryption lab. A regular app installer for your existing system.</p><div class="download-meta"><span data-version>0.1.0-alpha.1</span><span>ARM64 · .deb installer</span><span id="installer-size">Loading size…</span></div><a class="button primary" id="download-installer" href="https://github.com/brandenskaggs-rgb/signalpier/releases/download/v0.1.0-alpha.1/signalpier_0.1.0-alpha.1_arm64.deb">Download Pi app installer (.deb) ↓</a><p class="fine"><strong>Your download is one file: <span style="overflow-wrap:anywhere">signalpier_0.1.0-alpha.1_arm64.deb</span>.</strong> Keep it intact. On the Pi, open it with the software installer, approve installation, then launch SignalPier from the application menu.</p><p class="fine" id="release-message">Alpha release · <span id="release-date">2026-11-07</span>. Software tested under ARM64 emulation; physical Pi/receiver acceptance pending.</p><p class="fine">Downloading on Windows? Save the .deb file and transfer it to your Pi. Windows may show it as an archive; it runs on 64-bit Raspberry Pi OS. Do not extract its contents.</p><details class="checksum"><summary>Checksum and release details</summary><strong>SHA-256</strong><span id="installer-sha">See GitHub release checksums</span><p><a href="{REPO}/releases">Developer source archives and release history ↗</a></p></details></article>
<section class="section"><div class="section-head"><div><p class="eyebrow">THREE SIMPLE STEPS</p><h2>Get to your radio desk.</h2></div></div><div class="features"><article class="feature"><h3>1. Download</h3><p>Click the button above in your Pi's browser. It downloads the application, not an operating system.</p></article><article class="feature"><h3>2. Install</h3><p>Open the .deb file with your Pi's package installer. If an archive manager opens, close it and use Open With to select the software installer. It adds SignalPier and its receiver tools.</p></article><article class="feature"><h3>3. Open SignalPier</h3><p>Launch SignalPier from the application menu, or open <strong>http://127.0.0.1:8765</strong> on the Pi.</p></article></div><p class="fine">No graphical package installer? See the <a href="guide.html#install">one-command installation option</a>.</p></section>
''','Download the SignalPier app installer for Raspberry Pi 3 running 64-bit Raspberry Pi OS. No OS image or reflashing required.')

page('guide.html','Get started',f'''
<section class="page-title"><p class="eyebrow">GET STARTED / A REGULAR PI APP</p><h1>Install it.<br>Make it your station.</h1><p>SignalPier runs on your existing 64-bit Raspberry Pi OS. No SD-card flashing or operating-system replacement.</p></section>
<div class="guide-layout"><nav class="guide-nav" aria-label="Guide sections"><a href="#install">Install the app</a><a href="#open">Open the dashboard</a><a href="#receiver">Connect a receiver</a><a href="#validation">Compatibility</a><a href="#faq">Questions</a></nav><div class="guide-content">
<h2 id="install">Download and install.</h2><p>On the Pi, <a href="downloads.html"><u>download SignalPier</u></a>. Open the downloaded <code>.deb</code> file with the system's software installer and approve the installation. An internet connection is needed to install any missing receiver packages.</p><p><strong>Do not extract the .deb.</strong> It is the application installer. Windows can download and store it, but installation happens on the Pi. If opening it shows archive contents, close that window and choose the Pi's software installer with Open With, or use the command below.</p><p>If your desktop doesn't provide a graphical .deb installer, open a terminal in the Downloads folder and run:</p><div class="copy-line"><pre id="install-command">sudo apt install ./signalpier_0.1.0-alpha.1_arm64.deb</pre><button data-copy="install-command">Copy</button></div>
<h2 id="open">Open your radio desk.</h2><p>Launch <strong>SignalPier</strong> from the application menu. It opens your browser at <strong>http://127.0.0.1:8765</strong>. You can also enter that address yourself. The background service starts automatically after installation and at boot.</p><p>The four sections are Spectrum, Station clock, Encryption lab, and Settings. Try a demo capture to learn the controls, or connect a receiver and select Hardware.</p><details><summary>Use a laptop as the Pi's screen</summary><p>Keep this command running on your laptop, substituting your Pi username and hostname:</p><pre>ssh -N -L 8765:127.0.0.1:8765 YOUR_USER@YOUR_PI</pre><p>Then open http://127.0.0.1:8765 on the laptop. The Pi performs reception; the laptop renders the dashboard.</p></details>
<h2 id="updates">Offline use and updates.</h2><p>After installation, reception, the station clock, demo mode and encryption lab work offline. When internet is available, SignalPier checks this website for a newer release and shows an update notice. Click <strong>Install update</strong> to download and install it; nothing installs automatically. The dashboard reconnects after installation. Online NOAA readings require internet.</p><h2 id="receiver">Connect your SDR.</h2><ol><li>Connect a supported RTL-SDR USB receiver and an appropriate antenna to the Pi.</li><li>Stop any other program using the same dongle.</li><li>Choose Hardware on the Spectrum tab, use receiver index 0 for the first receiver, and start a short capture.</li><li>For compatible weather sensors and supported device protocols, choose packet decoding and enter the device frequency.</li></ol><p>Hardware mode invokes actual rtl_power and rtl_433 receiver tools. Demo mode is separately labeled. Not every signal has a supported decoder; this release does not implement P25 voice decoding or encrypted over-the-air messaging.</p><p>RTL-SDR Blog V3 is receive-only. This alpha does not transmit or program handheld/mobile radios.</p><p>Receiver support depends on the installed driver. Standard RTL2832U dongles are the initial target. RTL-SDR Blog V4 requires a sufficiently recent compatible driver, which older distribution packages may not include.</p>
<h2 id="validation">Compatibility and test status.</h2><p>Primary target: <strong>Raspberry Pi 3 Model B / B+, 1 GB RAM, Raspberry Pi OS 64-bit</strong> with Python 3.10 or newer. 32-bit Pi OS cannot install the ARM64 package. Pi 4/5 are secondary targets; the original C.H.I.P. is unsupported.</p><p>The application and package are tested in an ARM64 environment under emulation. The actual ARM64 rtl_433 decoder successfully decoded a recorded Acurite sensor sample. Desktop and mobile browser tests cover the interface.</p><div class="notice">This is an alpha release. Physical Pi 3 reception, thermal behavior, power stability, and performance with your particular receiver still need hardware acceptance. No simulated capture is presented as live reception.</div><p>Resource controls: one receiver task at a time, bounded captures, 30 plotted sweeps with at most 1,024 points each, compact status polling, and a 256 MB service memory limit. These are configured limits, not measured Pi performance claims.</p>
<section class="faq" id="faq"><h2>Useful answers.</h2><details><summary>Do I need to install an operating system?</summary><p>No. Install this application on your existing supported 64-bit Raspberry Pi OS.</p></details><details><summary>Does it read real radio signals?</summary><p>Yes, through a supported SDR and antenna in Hardware mode. The spectrum tool measures received energy; rtl_433 decodes supported sensor/device protocols. Receiving and decoding are different operations.</p></details><details><summary>Does the Pi need a screen?</summary><p>No. Use the laptop connection above. A desktop Pi can open the dashboard directly.</p></details><details><summary>Can it encrypt my radio channels?</summary><p>The included lab encrypts your own text locally with AES-256-GCM. It does not configure a radio's encryption or transmit messages. Those require a separate compatible radio integration.</p></details><details><summary>How do I troubleshoot or uninstall?</summary><p>Check <code>systemctl status signalpier</code> and <code>journalctl -u signalpier -n 50 --no-pager</code>. Uninstall with <code>sudo apt remove signalpier</code>. Report issues with your Pi, OS and receiver model, excluding private data.</p></details></section></div></div>
''','Install SignalPier as a normal application on an existing Raspberry Pi 3. Download the .deb, install it, and open the dashboard.')

page('roadmap.html','The open-source project',f'''
<section class="page-title"><p class="eyebrow">THE PROJECT / OPEN FROM THE START</p><h1>A radio desk<br>you can make your own.</h1><p>SignalPier brings a small set of dependable tools into one interface. The application is MIT-licensed, its app installer is documented, and its limitations are visible.</p></section><div class="roadmap"><article><p class="eyebrow">AVAILABLE / ALPHA</p><h3>The station foundation</h3><ul><li>rtl_power spectrum adapter</li><li>rtl_433 packet adapter</li><li>Station clock and solar map</li><li>Local AES-GCM message lab</li><li>Capture exports and test suite</li><li>Offline use and user-started updates</li></ul></article><article><p class="eyebrow">NEXT / HARDWARE ACCEPTANCE</p><h3>Prove it at the antenna</h3><ul><li>Pi 3 boot and provision checks</li><li>Receiver and driver matrix</li><li>SDR++ comparison captures</li><li>Thermal and memory soak tests</li><li>Validated release promotion</li></ul></article><article><p class="eyebrow">PLANNED / NOT INCLUDED YET</p><h3>Connect the station</h3><ul><li>Transmit-capable hardware integration</li><li>Model-specific radio programming</li><li>Persistent signal activity log</li><li>Recorded IQ inspection</li><li>Reticulum/LXMF message nodes</li><li>Pocket25 remote-receiver guide</li><li>Own-station TAK telemetry</li></ul></article></div><div class="repo-box"><p class="eyebrow">GITHUB / SOURCE + ISSUES + RELEASES</p><h2>Read it. Run it. Improve it.</h2><p>The core server uses Python's standard library. The interface is plain JavaScript and CSS. Small, understandable parts make this an approachable project to extend.</p><a class="button" href="{REPO}">Open SignalPier on GitHub ↗</a></div><section class="section"><div class="section-head"><div><p class="eyebrow">BUILT WITH OPEN TOOLS</p><h2>Credit where it's due.</h2></div></div><div class="features"><article class="feature"><h3>Native receiver tools</h3><p><a href="https://github.com/osmocom/rtl-sdr"><u>RTL-SDR</u></a> provides receiver utilities; <a href="https://github.com/merbanan/rtl_433"><u>rtl_433</u></a> provides protocol decoding. Their licenses remain separate from SignalPier's MIT license.</p></article><article class="feature"><h3>Maps and measurements</h3><p>World geometry comes from public-domain <a href="https://www.naturalearthdata.com/"><u>Natural Earth</u></a>. Space-weather observations come from <a href="https://www.swpc.noaa.gov/"><u>NOAA SWPC</u></a>.</p></article><article class="feature"><h3>A proven OS foundation</h3><p>The application installs on an existing <a href="https://www.raspberrypi.com/software/operating-systems/"><u>Raspberry Pi OS</u></a> 64-bit system. SignalPier is an independent project, not an official Raspberry Pi product.</p></article></div></section>
''','SignalPier is an MIT-licensed radio workbench with public source, an honest development roadmap, and documented Raspberry Pi app packaging.')
